    private static int atlasNumber(String path){
        if(path==null||!path.startsWith("/img/item-atlas-")||!path.endsWith(".png"))return -1;
        int begin=16,end=path.length()-4;
        if(begin>=end||end-begin>2)return -1;
        int n=0;
        for(int i=begin;i<end;i++){
            char c=path.charAt(i);
            if(c<'0'||c>'9')return -1;
            n=n*10+c-'0';
        }
        return n<=20?n:-1;
    }
