    static byte[] decode(String b64){
        try(GZIPInputStream in=new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(b64)))){return in.readAllBytes();}
        catch(IOException e){throw new IllegalStateException("AppCenter asset damaged",e);}
    }
